from 写入第二遍 import add
add('02_003',4,'16:9，门内低机位全景，门口来者的深色腿部占画面右侧近层，青梅男与青梅女缩在左后；先由门内空隙看二人转身，再轻移至腿边停下。','青梅男闻声骤转，前脚跨向门口、后脚撑开，右手扣紧低处刀柄，把身体挡到青梅女前面；青梅女跟着转头，圆睁的双眼越过他肩侧望向门口。来者在门内停步，双腿形成深色遮挡；男将刀斜压在身侧，问话第一声打了结，仍牢牢守住二人之间的位置。','灰褐木地板向左后延伸，米褐木墙退在二人身后，门框边缘从右侧竖出，门外浅冷灰。','门外冷白光从来者背侧入室，室内二人面部由右侧拱窗柔光照明。','男跨步踩木板一声短响，刀具在衣侧轻磕，门轴停止。',ja=['こんな所に人がいたとは。','だ、誰だ？！'],tone='来者低声意外；男由受惊转警戒，结巴后把问句顶出去。',kind='mixed',meaning='男挡到同伴前持刀警戒；门口只露腿部，暂不揭晓身份。',characters=['青梅男','青梅女','门口来者'],card={'opening':'门外短声打断争执。','beats':['男横跨护住同伴，女从他肩旁望门口','来者停步发声，男抓紧刀柄问身份'],'coupling':'护人站位早于问话形成，女在遮挡后仍有独立视线。','landing':'来者腿在近处，男守在女与来者之间。'})
add('02_004',5,'16:9，青梅女头肩近景居画面右侧，青梅男盔面在左后；固定机位从门口方向朝房内看，女的脸成为清晰焦点。','来者的话从门口压进来，青梅女先屏住呼吸，眼睛追向对方脸的画外高度；她眉毛抬开，嘴由小圆口动成欲喊名字的形，刚说到“你是”便顿住，肩膀向前倾出一点。青梅男仍对着门口，盔面微偏向女，握刀的手留在画外低处。','两人轮廓旁是米褐木墙，深褐竖梁模糊地立在左后，右侧门光落在窄条地面。','右侧窗光柔和照亮女双眼，来者身后的门光只给盔边一道冷亮边。','木门停止后的轻颤声，男衣袖随转盔面擦响。',ja=['ここで一体何が起きてるのか、さっさと話せ。','あ…あなたは…！'],tone='来者不耐烦、带粗鲁命令感；女认出后声音很轻地冲出，停在未说完的称呼上。',kind='mixed',meaning='女认出门口人但未报名字；身份悬念保留。',characters=['青梅女','青梅男','门口来者'],card={'opening':'同伴还在戒备，女先认出来者。','beats':['听命令时屏息仰视','眉抬眼圆，身体微前倾，说到称呼便停'],'coupling':'识别发生在眼神与说话受阻上。','landing':'惊讶留在女脸上，门口脸仍在画外。'})
add('03_002',2,'16:9，俯看平台石铺地面的近景，青裙摆与一条腿沿画面右侧斜切，散落小体从左下排向左上；沿地面缓缓推入，腿部遮挡保持右侧。','青的裙摆被短风托开又垂回，白色有尾小体在她腿边乱拱，一条细尾抽动两下，另一个扁下的白段轻轻滑过碎石；地上的深灰拖痕保持在各自落点，脚边碎屑受尾部搅动散开。','灰绿石铺地面上有深灰拖痕和浅灰碎石，远处石块纹理逐渐淡入米灰薄尘。','正上方云天冷白漫射，石面缝隙深灰，亮处偏灰绿。','细碎黏软摆动声夹着石屑小响，空旷平台风声重新清晰。',kind='action',phase='state',node={'场景':'青与武士对峙的平台','青.持物':'双手准备抓取小体'},meaning='由地上散落小体和青腿部返回战场，保留深色拖痕而不指定成血迹。',characters=['青','白色有尾小体群'])
